fn merge_sort(mut arr: Vec<i32>) -> Vec<i32> {
    let len = arr.len();
    if len <= 1 {
        return arr;
    }

    let mid = len / 2;
    let left = merge_sort(arr.drain(..mid).collect());
    let right = merge_sort(arr);

    merge(left, right)
}

fn merge(left: Vec<i32>, right: Vec<i32>) -> Vec<i32> {
    match (left.split_first(), right.split_first()) {
        (Some((&l, l_rest)), Some((&r, r_rest))) => {
            if l < r {
                let mut result = vec![l];
                result.extend(merge(l_rest.to_vec(), right));
                result
            } else {
                let mut result = vec![r];
                result.extend(merge(left, r_rest.to_vec()));
                result
            }
        }
        (Some(_), None) => left,
        (None, Some(_)) => right,
        (None, None) => Vec::new(),
    }
}

fn main() {
    let data = vec![34, 7, 23, 32, 5, 62];
    let sorted_data = merge_sort(data);
    println!("{:?}", sorted_data);
}
```

